    "mode": "import",
    "mcode": "let\n\t    /*\n\t    【查询名称】S3 C1 成本变化步行图 BW 取数\n\t    【对应报表】L2-01-04 S3 C1成本变化步行图VS上月\n\t    【BW对象】Cube:ZRCO_CP011，Query:ZRCO_CP011/ZRCO_CP011_Q0012\n\t    【说明】\n\t        1、数据源：SAP BW QAS + SharePoint「L2-01-04 S3 C1成本变化步行图VS上月指标映射.xlsx」的 指标名称排序 / 产品排序 / 矿体排序 三张 Sheet\n\t        2、维度：产品 [ZCP]、矿体 [ZKT]、单位 [4ZRCO_CP011-ZUNIT]\n\t        3、指标：13 个 —— 10 项成本要素 + C1成本本月实际 / C1成本上个月 / 产量(品位回收率)\n\t        4、循环：p_月报起始日期 ~ p_月报终止日期 逐月取数后纵向合并，[ZMSDQNY] 传 YYYYMM 文本\n\t        5、清洗与长表化：不做 null → 0，13 个指标列逆透视成 [指标名称] / [指标值]\n\t        6、排序：依次左连接 指标名称排序 / 产品排序 / 矿体排序\n\t    */\n\t    // ========== 1. 读取 SharePoint 映射表 ==========\n\t    // 列出财经 SharePoint 站点文件\n\t    源 = SharePoint.Files(财经SharePoint站点, [ApiVersion = 15]),\n\t    // 筛出本表指标映射 xlsx 并取二进制内容\n\t    指标映射文件 = Table.SelectRows(源, each Text.Contains([Name], \"L2-01-04 S3 C1成本变化步行图VS上月指标映射\") and [Extension] = \".xlsx\"){0}[Content],\n\t    // 工作簿只解析一次，各 Sheet 共用\n\t    指标映射工作簿 = Excel.Workbook(指标映射文件, true),\n\t    // 按匹配键去重，保证左连接一对一\n\t    指标排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"指标名称排序\", Kind = \"Sheet\"]}[Data], {\"指标名称\"}),\n\t    产品排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"产品排序\", Kind = \"Sheet\"]}[Data], {\"产品\"}),\n\t    矿体排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"矿体排序\", Kind = \"Sheet\"]}[Data], {\"矿体\"}),\n\t\n\t    // ========== 2. 连接 BW QAS ==========\n\t    // 中文返回 + 开启内置结构 + 大批量拉取\n\t    数据源 = SapBusinessWarehouse.Cubes(QAS服务器, 系统编号, 客户端ID, [Implementation=\"2.0\", LanguageCode=\"ZH\", EnableStructures=true, BatchSize=500000000]),\n\t    // 定位 Cube，只在循环外实例化一次\n\t    立方体 = 数据源{[Name=\"ZRCO_CP011\"]}[Data],\n\t    // 定位 Query，作为逐月变换模板\n\t    基础查询 = 立方体{[Id=\"ZRCO_CP011/ZRCO_CP011_Q0012\"]}[Data],\n\t\n\t    // ========== 3. 生成月份序列 ==========\n\t    // 起止月份取自参数，跨月需后延 p_月报终止日期\n\t    起始月份 = p_月报起始日期,\n\t    结束月份 = p_月报终止日期,\n\t    月份序列 = List.Generate(() => 起始月份, each _ <= 结束月份, each Date.AddMonths(_, 1)),\n\t    // 转成 BW 要求的 YYYYMM 文本\n\t    月份文本列表 = List.Transform(月份序列, each Text.From(Date.Year(_) * 100 + Date.Month(_))),\n\t\n\t    // ========== 4. 单月取数函数 ==========\n\t    // 入参 month 为 YYYYMM 文本\n\t    查询单月 = (month as text) as table =>\n\t        let\n\t            // 应用 BW 变换：期间参数 → 展开 3 个维度 → 挂载 13 个度量\n\t            查询结果 = Cube.Transform(基础查询, {\n\t                {Cube.ApplyParameter, \"[ZMSDQNY]\", {month}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[ZCP]\", {\"[ZCP].[LEVEL01]\"}, {\"产品\"}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[ZKT]\", {\"[ZKT].[LEVEL01]\"}, {\"矿体\"}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[4ZRCO_CP011-ZUNIT]\", {\"[4ZRCO_CP011-ZUNIT].[LEVEL01]\"}, {\"单位\"}},\n\t                {Cube.AddMeasureColumn, \"其他\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM24CGG1HKOHR]\"},\n\t                {Cube.AddMeasureColumn, \"人工\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM281W2DP3CME]\"},\n\t                {Cube.AddMeasureColumn, \"维修费用\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCOYBL]\"},\n\t                {Cube.AddMeasureColumn, \"外部服务\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCP4N5]\"},\n\t                {Cube.AddMeasureColumn, \"材料成本\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCPAYP]\"},\n\t                {Cube.AddMeasureColumn, \"能源费\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCPHA9]\"},\n\t                {Cube.AddMeasureColumn, \"运费\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCPNLT]\"},\n\t                {Cube.AddMeasureColumn, \"递延剥离\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCPTXD]\"},\n\t                {Cube.AddMeasureColumn, \"在产品变动\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCQ08X]\"},\n\t                {Cube.AddMeasureColumn, \"外购矿石\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ1PM28A7CWCQ6KH]\"},\n\t                {Cube.AddMeasureColumn, \"C1成本上个月\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ3FWE24L2I38Y1D]\"},\n\t                {Cube.AddMeasureColumn, \"C1成本本月实际\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ3FWE24L2I3B87L]\"},\n\t                {Cube.AddMeasureColumn, \"产量(品位回收率)\", \"[4VGQHR12MHZ3FWE24L2I3JAZ5].[4VGQHR12MHZ3FWE5SVNOORXM9]\"}\n\t            }),\n\t            // 加载日期取该月 1 日，供日期表关系与切片器筛选\n\t            添加加载日期 = Table.AddColumn(查询结果, \"加载日期\", each #date(Number.From(Text.Start(month, 4)), Number.From(Text.End(month, 2)), 1), type date),\n\t            // 保留 产品 / 矿体 / 单位 / 加载日期，13 个度量列逆透视\n\t            逆透视长表 = Table.UnpivotOtherColumns(添加加载日期, {\"产品\", \"矿体\", \"单位\", \"加载日期\"}, \"指标名称\", \"指标值\")\n\t        in\n\t            逆透视长表,\n\t\n\t    // ========== 5. 逐月取数并合并 ==========\n\t    // 各月结构一致，直接纵向拼接\n\t    各月结果 = List.Transform(月份文本列表, 查询单月),\n\t    合并结果 = Table.Combine(各月结果),\n\t\n\t    // ========== 6. 左连接三张排序映射表 ==========\n\t    // 依次按 指标名称 / 产品 / 矿体 匹配，LeftOuter 保留未匹配行\n\t    左连接指标排序 = Table.NestedJoin(合并结果, {\"指标名称\"}, 指标排序映射表, {\"指标名称\"}, \"映射指标\", JoinKind.LeftOuter),\n\t    // 每步只展开对应的排序字段\n\t    展开指标排序 = Table.ExpandTableColumn(左连接指标排序, \"映射指标\", {\"指标名称排序\"}, {\"指标名称排序\"}),\n\t\n\t    左连接产品排序 = Table.NestedJoin(展开指标排序, {\"产品\"}, 产品排序映射表, {\"产品\"}, \"映射产品\", JoinKind.LeftOuter),\n\t    展开产品排序 = Table.ExpandTableColumn(左连接产品排序, \"映射产品\", {\"产品排序\"}, {\"产品排序\"}),\n\t\n\t    左连接矿体排序 = Table.NestedJoin(展开产品排序, {\"矿体\"}, 矿体排序映射表, {\"矿体\"}, \"映射矿体\", JoinKind.LeftOuter),\n\t    展开矿体排序 = Table.ExpandTableColumn(左连接矿体排序, \"映射矿体\", {\"矿体排序\"}, {\"矿体排序\"})\n\tin\n\t    展开矿体排序",
