    "mcode": "let\n\t    /*\n\t    【查询名称】物料单耗月表 BW 取数\n\t    【对应报表】L2-01-14 物料单耗月表\n\t    【BW对象】Cube:ZRCO_CP011，Query:ZRCO_CP011/ZRCO_CP011_Q0013\n\t    【说明】\n\t        1、数据源：SAP BW QAS + SharePoint「L2-01-14 物料单耗月表指标映射.xlsx」的 矿体排序 / 区域排序 / 指标名称排序 / 主要耗材用量排序 四张 Sheet\n\t        2、维度：矿体 [ZKT]、主要耗材用量 [ZINDID]、单位 [4ZRCO_CP011-ZUNIT]、生产阶段区域 [ZTDISTRCT]\n\t        3、指标：8 个 —— 上月完成 / 本月完成 / 环比 / 环比±% / 年计划 / 年累计 / 完成率 / 本月计划\n\t        4、循环：p_月报起始日期 ~ p_月报终止日期 逐月取数后纵向合并，[ZMSDQNY] 传 YYYYMM 文本\n\t        5、清洗与长表化：8 个指标列 null → 0，逆透视成 [指标名称] / [指标值]\n\t        6、排序：依次左连接 指标名称排序 / 矿体排序 / 区域排序 / 主要耗材用量排序，区域用「区域」键匹配\n\t        7、迁移：本表已由 ZRCO_CP004 / Q0011 切到 ZRCO_CP011 / Q0013\n\t    */\n\t\n\t    // ========== 1. 读取 SharePoint 映射表 ==========\n\t    // 列出财经 SharePoint 站点文件\n\t    源 = SharePoint.Files(财经SharePoint站点, [ApiVersion = 15]),\n\t    // 筛出本表指标映射 xlsx 并取二进制内容\n\t    指标映射文件 = Table.SelectRows(源, each Text.Contains([Name], \"L2-01-14 物料单耗月表指标映射\") and [Extension] = \".xlsx\"){0}[Content],\n\t    // 工作簿只解析一次，各 Sheet 共用\n\t    指标映射工作簿 = Excel.Workbook(指标映射文件, true),\n\t    // 按匹配键去重，保证左连接一对一\n\t    矿体排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"矿体排序\", Kind = \"Sheet\"]}[Data], {\"矿体\"}),\n\t    区域排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"区域排序\", Kind = \"Sheet\"]}[Data], {\"区域\"}),\n\t    指标名称排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"指标名称排序\", Kind = \"Sheet\"]}[Data], {\"指标名称\"}),\n\t    主要耗材用量排序映射表 = Table.Distinct(指标映射工作簿{[Item = \"主要耗材用量排序\", Kind = \"Sheet\"]}[Data], {\"主要耗材用量\"}),\n\t\n\t    // ========== 2. 连接 BW QAS ==========\n\t    // 中文返回 + 开启内置结构 + 大批量拉取\n\t    数据源 = SapBusinessWarehouse.Cubes(QAS服务器, 系统编号, 客户端ID, [Implementation=\"2.0\", LanguageCode=\"ZH\", EnableStructures=true, BatchSize=500000000]),\n\t    // 定位 Cube，只在循环外实例化一次\n\t    立方体 = 数据源{[Name=\"ZRCO_CP011\"]}[Data],\n\t    // 定位 Query，作为逐月变换模板\n\t    基础查询 = 立方体{[Id=\"ZRCO_CP011/ZRCO_CP011_Q0013\"]}[Data],\n\t\n\t    // ========== 3. 生成月份序列 ==========\n\t    // 起止月份取自参数，跨月需后延 p_月报终止日期\n\t    起始月份 = p_月报起始日期,\n\t    结束月份 = p_月报终止日期,\n\t    月份序列 = List.Generate(() => 起始月份, each _ <= 结束月份, each Date.AddMonths(_, 1)),\n\t    // 转成 BW 要求的 YYYYMM 文本\n\t    月份文本列表 = List.Transform(月份序列, each Text.From(Date.Year(_) * 100 + Date.Month(_))),\n\t\n\t    // ========== 4. 单月取数函数 ==========\n\t    // 入参 month 为 YYYYMM 文本\n\t    查询单月 = (month as text) as table =>\n\t        let\n\t            // 应用 BW 变换：期间参数 → 展开 4 个维度 → 挂载 8 个度量\n\t            查询结果 = Cube.Transform(基础查询, {\n\t                {Cube.ApplyParameter, \"[ZMSDQNY]\", {month}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[ZKT]\", {\"[ZKT].[LEVEL01]\"}, {\"矿体\"}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[ZINDID]\", {\"[ZINDID].[LEVEL01]\"}, {\"主要耗材用量\"}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[4ZRCO_CP011-ZUNIT]\", {\"[4ZRCO_CP011-ZUNIT].[LEVEL01]\"}, {\"单位\"}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[ZTDISTRCT]\", {\"[ZTDISTRCT].[LEVEL01]\"}, {\"生产阶段区域\"}},\n\t                {Cube.AddMeasureColumn, \"上月完成\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV0V2W]\"},\n\t                {Cube.AddMeasureColumn, \"本月完成\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV11EG]\"},\n\t                {Cube.AddMeasureColumn, \"环比\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV17Q0]\"},\n\t                {Cube.AddMeasureColumn, \"环比±%\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV1E1K]\"},\n\t                {Cube.AddMeasureColumn, \"年计划\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV1KD4]\"},\n\t                {Cube.AddMeasureColumn, \"年累计\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV1QOO]\"},\n\t                {Cube.AddMeasureColumn, \"完成率\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ1PM20O1UKV23BS]\"},\n\t                {Cube.AddMeasureColumn, \"本月计划\", \"[4VGQHR12MHZ1PM20O1UKV6NO8].[4VGQHR12MHZ3FX01NES1EI6GT]\"}\n\t            }),\n\t            // 加载日期取该月 1 日，供日期表关系与切片器筛选\n\t            添加加载日期 = Table.AddColumn(查询结果, \"加载日期\", each #date(Number.From(Text.Start(month, 4)), Number.From(Text.End(month, 2)), 1), type date),\n\t            // 8 个指标列 null → 0\n\t            空值替换为0 = Table.ReplaceValue(添加加载日期, null, 0, Replacer.ReplaceValue,\n\t                {\"上月完成\", \"本月完成\",  \"环比\", \"环比±%\",\"年计划\", \"年累计\",\"完成率\",\"本月计划\"}\n\t            ),\n\t            // 保留 4 个维度与加载日期，8 个指标列逆透视\n\t            逆透视长表 = Table.UnpivotOtherColumns(空值替换为0, {\"生产阶段区域\",\"主要耗材用量\", \"矿体\", \"单位\", \"加载日期\"}, \"指标名称\", \"指标值\")\n\t        in\n\t            逆透视长表,\n\t\n\t    // ========== 5. 逐月取数并合并 ==========\n\t    // 各月结构一致，直接纵向拼接\n\t    各月结果 = List.Transform(月份文本列表, 查询单月),\n\t    合并结果 = Table.Combine(各月结果),\n\t\n\t    // ========== 6. 依次左连接四张排序映射表 ==========\n\t    // 按 指标名称 / 矿体 / 生产阶段区域→区域 / 主要耗材用量 匹配\n\t    左连接指标排序 = Table.NestedJoin(合并结果, {\"指标名称\"}, 指标名称排序映射表, {\"指标名称\"}, \"映射指标\", JoinKind.LeftOuter),\n\t    展开指标排序 = Table.ExpandTableColumn(左连接指标排序, \"映射指标\", {\"指标名称排序\"}, {\"指标名称排序\"}),\n\t    左连接矿体排序 = Table.NestedJoin(展开指标排序, {\"矿体\"}, 矿体排序映射表, {\"矿体\"}, \"映射矿体\", JoinKind.LeftOuter),\n\t    展开矿体排序 = Table.ExpandTableColumn(左连接矿体排序, \"映射矿体\", {\"矿体排序\"}, {\"矿体排序\"}),\n\t    左连接区域排序 = Table.NestedJoin(展开矿体排序, {\"生产阶段区域\"}, 区域排序映射表, {\"区域\"}, \"映射区域\", JoinKind.LeftOuter),\n\t    展开区域排序 = Table.ExpandTableColumn(左连接区域排序, \"映射区域\", {\"区域排序\"}, {\"区域排序\"}),\n\t    左连接耗材排序 = Table.NestedJoin(展开区域排序, {\"主要耗材用量\"}, 主要耗材用量排序映射表, {\"主要耗材用量\"}, \"映射耗材\", JoinKind.LeftOuter),\n\t    // 每步只展开对应的排序字段\n\t    展开耗材排序 = Table.ExpandTableColumn(左连接耗材排序, \"映射耗材\", {\"主要耗材用量排序\"}, {\"主要耗材用量排序\"})\n\tin\n\t    展开耗材排序",
