    "mcode": "let\n\t    /*\n\t    【查询名称】财务费用汇总表 BW 取数\n\t    【对应报表】L2-03-02 财务费用汇总表\n\t    【BW对象】Cube:ZRFI_CP010，Query:ZRFI_CP010/ZRFI_CP010_Q0001\n\t    【说明】\n\t        1、数据源：SAP BW QAS + SharePoint「L2-03-02 财务费用汇总表指标映射.xlsx」的 指标排序 / 结构排序 两张 Sheet\n\t        2、维度：BW 内置结构展开为 [结构]，另取 MEMBER_UNIQUE_NAME 生成 [结构唯一ID] 作排序键\n\t        3、指标：18 个财务费用分项 —— 财务费用 / 筹资费用 / 汇兑损益 / 利息收入与支出 / 手续费 / 外汇套保损益 / 折现费用等\n\t        4、循环：p_月报起始日期 ~ p_月报终止日期 逐月取数后纵向合并，[ZMSDQNY] 传 YYYYMM 文本\n\t        5、清洗与长表化：逆透视成 [指标名称] / [指标值] 后把 0 置为 null\n\t        6、排序：左连接 指标排序（键 指标名称）与 结构排序（键 结构唯一ID ↔ 结构UniqueName），并从结构排序带出 [期间]\n\t    */\n\t    // ========== 1. 读取 SharePoint 映射表 ==========\n\t    // 列出财经 SharePoint 站点文件\n\t    源 = SharePoint.Files(财经SharePoint站点, [ApiVersion = 15]),\n\t    // 筛出本表指标映射 xlsx 并取二进制内容\n\t    指标映射文件 = Table.SelectRows(源, each Text.Contains([Name], \"L2-03-02 财务费用汇总表指标映射\") and [Extension] = \".xlsx\"){0}[Content],\n\t    // 工作簿只解析一次，各 Sheet 共用\n\t    指标映射工作簿 = Excel.Workbook(指标映射文件, true),\n\t    // 指标排序按「指标名称」去重；结构排序按「结构UniqueName」去重\n\t    指标排序表 = Table.Distinct(指标映射工作簿{[Item = \"指标排序\", Kind = \"Sheet\"]}[Data], {\"指标名称\"}),\n\t    结构排序表 = Table.Distinct(指标映射工作簿{[Item = \"结构排序\", Kind = \"Sheet\"]}[Data], {\"结构UniqueName\"}),\n\t    // ========== 2. 连接 BW QAS ==========\n\t    // 中文返回 + 开启内置结构 + 大批量拉取\n\t    数据源 = SapBusinessWarehouse.Cubes(QAS服务器, 系统编号, 客户端ID, [Implementation=\"2.0\", LanguageCode=\"ZH\", EnableStructures=true, BatchSize=500000000]),\n\t    // 定位 Cube，只在循环外实例化一次\n\t    立方体 = 数据源{[Name=\"ZRFI_CP010\"]}[Data],\n\t    // 定位 Query，作为逐月变换模板\n\t    基础查询 = 立方体{[Id=\"ZRFI_CP010/ZRFI_CP010_Q0001\"]}[Data],\n\t    // 18 个度量唯一名共用一个前缀，下面各列只写后缀\n\t    度量前缀 = \"[4VGQHR12MHZ1PJONR9LZX5FVY].[4VGQHR12MHZ1PJONR9LZX\",\n\t    // ========== 3. 生成月份序列 ==========\n\t    // 起止月份取自参数，跨月需后延 p_月报终止日期\n\t    起始月份 = p_月报起始日期,\n\t    结束月份 = p_月报终止日期,\n\t    月份序列 = List.Generate(() => 起始月份, each _ <= 结束月份, each Date.AddMonths(_, 1)),\n\t    // 转成 BW 要求的 YYYYMM 文本\n\t    月份文本列表 = List.Transform(月份序列, each Text.From(Date.Year(_) * 100 + Date.Month(_))),\n\t    // ========== 4. 单月取数函数 ==========\n\t    // 入参 month 为 YYYYMM 文本\n\t    查询单月 = (month as text) as table =>\n\t        let\n\t            // 应用 BW 变换：期间参数 → 展开内置结构维度 → 挂载 18 个财务费用度量\n\t            查询结果 = Cube.Transform(基础查询, {\n\t                {Cube.ApplyParameter, \"[ZMSDQNY]\", {month}},\n\t                {Cube.AddAndExpandDimensionColumn, \"[4VGQHR12MHZ1PJONR9LZX6HTA]\", {\"[4VGQHR12MHZ1PJONR9LZX6HTA]\"}, {\"结构\"}},\n\t                {Cube.AddMeasureColumn, \"财务费用\", 度量前缀 & \"9AY6]\"},\n\t                {Cube.AddMeasureColumn, \"筹资费用\", 度量前缀 & \"BL4E]\"},\n\t                {Cube.AddMeasureColumn, \"汇兑损益\", 度量前缀 & \"BRFY]\"},\n\t                {Cube.AddMeasureColumn, \"集团内部资金占用费收入\", 度量前缀 & \"B25Q]\"},\n\t                {Cube.AddMeasureColumn, \"集团内部资金占用费支出\", 度量前缀 & \"A6JY]\"},\n\t                {Cube.AddMeasureColumn, \"金属流、邦普借款及其他利息支出\", 度量前缀 & \"ACVI]\"},\n\t                {Cube.AddMeasureColumn, \"净利息支出(利息支出+利息资本化)\", 度量前缀 & \"9H9Q]\"},\n\t                {Cube.AddMeasureColumn, \"利息收入\", 度量前缀 & \"AVU6]\"},\n\t                {Cube.AddMeasureColumn, \"利息收入-小计\", 度量前缀 & \"APIM]\"},\n\t                {Cube.AddMeasureColumn, \"利息支出\", 度量前缀 & \"9NLA]\"},\n\t                {Cube.AddMeasureColumn, \"利息支出资本化\", 度量前缀 & \"AJ72]\"},\n\t                {Cube.AddMeasureColumn, \"其他利息收入\", 度量前缀 & \"B8HA]\"},\n\t                {Cube.AddMeasureColumn, \"手续费\", 度量前缀 & \"BESU]\"},\n\t                {Cube.AddMeasureColumn, \"外汇套保损益\", 度量前缀 & \"CAEM]\"},\n\t                {Cube.AddMeasureColumn, \"银行借款利息支出\", 度量前缀 & \"A08E]\"},\n\t                {Cube.AddMeasureColumn, \"银行理财收益及票据贴现利息\", 度量前缀 & \"C432]\"},\n\t                {Cube.AddMeasureColumn, \"债券利息支出\", 度量前缀 & \"9TWU]\"},\n\t                {Cube.AddMeasureColumn, \"折现费用\", 度量前缀 & \"BXRI]\"}\n\t            }),\n\t            // 取 MEMBER_UNIQUE_NAME 作排序匹配键\n\t            添加结构唯一ID = Table.AddColumn(查询结果, \"结构唯一ID\", each Cube.AttributeMemberProperty([结构], \"[MEMBER_UNIQUE_NAME]\")),\n\t            // 加载日期取该月 1 日，供日期表关系与切片器筛选\n\t            添加加载日期 = Table.AddColumn(添加结构唯一ID, \"加载日期\", each #date(Number.From(Text.Start(month, 4)), Number.From(Text.End(month, 2)), 1), type date)\n\t        in\n\t            添加加载日期,\n\t    // ========== 5. 逐月取数并合并 ==========\n\t    // 各月结构一致，直接纵向拼接\n\t    各月结果 = List.Transform(月份文本列表, 查询单月),\n\t    合并宽表 = Table.Combine(各月结果),\n\t    // ========== 6. 宽表转长表 ==========\n\t    // 保留 结构 / 结构唯一ID / 加载日期，18 个度量列逆透视\n\t    逆透视长表 = Table.UnpivotOtherColumns(\n\t        合并宽表,\n\t        {\"结构\", \"结构唯一ID\", \"加载日期\"},\n\t        \"指标名称\",\n\t        \"指标值\"\n\t    ),\n\t    // ========== 7. 清洗零值 ==========\n\t    // [指标值] 的 0 置为 null，真实为 0 的行也会显示空白\n\t    清洗空值 = Table.ReplaceValue(逆透视长表, 0, null, Replacer.ReplaceValue, {\"指标值\"}),\n\t    // ========== 8. 左连接两张排序映射表 ==========\n\t    // 先按「指标名称」匹配指标排序，再按「结构唯一ID」=「结构UniqueName」匹配结构排序，带出 [期间]\n\t    左连接指标排序 = Table.NestedJoin(清洗空值, {\"指标名称\"}, 指标排序表, {\"指标名称\"}, \"指标映射临时\", JoinKind.LeftOuter),\n\t    展开指标排序 = Table.ExpandTableColumn(左连接指标排序, \"指标映射临时\", {\"指标排序\"}, {\"指标排序\"}),\n\t    左连接结构排序 = Table.NestedJoin(展开指标排序, {\"结构唯一ID\"}, 结构排序表, {\"结构UniqueName\"}, \"结构映射临时\", JoinKind.LeftOuter),\n\t    // 只展开对应的排序字段\n\t    展开结构排序 = Table.ExpandTableColumn(左连接结构排序, \"结构映射临时\", {\"结构排序\", \"期间\"}, {\"结构排序\", \"期间\"})\n\tin\n\t    展开结构排序",
    "lines": 96,
